head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/jquery-1.11.0.min.js");
scwin.vScrenID = "ULDSTF05241.xml";
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar;
// mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.cm.InfoMenuID());
scwin.vBzProcsNo = "";
scwin.vListEligtyTpCd = "F";
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.trsIdx; // insert, update 구분
scwin.pMngId = js_id; //로그인 ID
scwin.selRow = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchCode = function() {
    /*
     * DELIST_REAL_INVSTG_RSN_CD 02549-상장폐지 실질심사 사유코드(10: 회생절차개시신청(삭제)  화면에서만 안보여달라고 함)
     * LIST_ELIGTY_DELIB_RSLT_CD 04414-상장적격성심의결과코드
     * AUDT_OPIN_TP_CD 01179-감사의견구분코드
     */
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='DELIST_REAL_INVSTG_RSN_CD','LIST_ELIGTY_DELIB_RSLT_CD','AUDT_OPIN_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        scwin.fr_SecuGrpId = arrPar[0].SECUGRP_ID;
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        scwin.fn_initItem();
        scwin.fn_list_sync();
        buttonSet.setInsertStatus();
    }
};
scwin.fn_initItem = function() {
    buttonSet.setInsertStatus();
    dts_Mst.removeAll();
    dts_Mst.insertRow();
    dts_Mst.setCellData(1, "LIST_ELIGTY_TP_CD", scwin.vListEligtyTpCd);
    scwin.vBzProcsNo = ""; //초기화 

};


/**
 *	상장적격성 실질심사 내역
 */
scwin.fn_list_sync = function() {
    var url = "/RealInvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=realInvstgList&inputMessageId=REALINVSTG_DETAIL_LIST_NEW" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&LIST_ELIGTY_TP_CD=" + scwin.vListEligtyTpCd;
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};



/**
 *	실질심사 결과 등 그리드 조회
 */
scwin.fn_list_allDtl_sync = function(procsCd, dataSet, row) {
    if (typeof row != "undefined") {
        scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    }
    var url = "/RealInvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=realInvstgDtlDetail&inputMessageId=REALINVSTG_DTLDETAIL_LIST" + "&LIST_ELIGTY_PROCS_CD=" + procsCd + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dataSet.DataID = encodeURI(url);
    dataSet.Reset();
};


/**
 *	실질심사 사유 및 사유발생일 세부내역
 */
scwin.fn_OpenDetail = function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO");
    var url = "/RealInvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=realInvstgDetail&inputMessageId=REALINVSTG_DETAIL_LIST_NEW" + "&BZ_PROCS_NO=" + scwin.vBzProcsNo + "&LIST_ELIGTY_TP_CD=" + scwin.vListEligtyTpCd;
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        return false;
    }
    if (!scwin.eachDateCheck("3. 이의신청서 제출일", edt_EINSPRUCH_SUBMIT_DD)) {
        return false;
    }
    return true;
};
scwin.eachDateCheck = function(comment, dateComponent) {
    if (dateComponent.getText() != "") {
        if (!scwin.checkDate(dateComponent.getText())) {
            $c.win.alert(comment + " 날짜형식을 확인하세요");
            dateComponent.focus();
            return false;
        }
    }
    return true;
};


/**
 *	저장, 수정시 사유(결과,결과(직접)) 입력여부 확인
 */
scwin.fn_checkRsnVal = function() {
    if (dts_Dtl1.getTotalRow() == 0) {
        $c.win.alert("상장폐지 사유 및 사유발생일을 입력하세요.");
        return false;
    }
    var occrDd = "";
    var isOkDate = true;
    for (j = 1; j <= dts_Dtl1.getTotalRow(); j++) {
        if (dts_Dtl1.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") == "") {
            $c.win.alert(j + "번째 [1. 상장폐지 사유 및 사유발생일 '사유']를 입력하세요.");
            dtl_Grd1.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd1.focus();
            return false;
        }
        if (dts_Dtl1.getCellData(j, "OCCR_DD") == "") {
            $c.win.alert(j + "번째 [1. 상장폐지 사유 및 사유발생일 '일자']를 입력하세요.");
            dtl_Grd1.SetColumn("OCCR_DD");
            dtl_Grd1.focus();
            return false;
        }
        occrDd = dts_Dtl1.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            $c.win.alert(j + "번째 [1. 상장폐지 사유 및 사유발생일 '일자'] 형식을 확인하세요.");
            return false;
        }
    }
    for (j = 1; j <= dts_Dtl2.getTotalRow(); j++) {
        if (dts_Dtl2.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") == "" && dts_Dtl2.getCellData(j, "LIST_ELIGTY_PROCS_RSN_CONTN") == "") {
            $c.win.alert(j + "번째 [2. 감사의견 및 감사보고서 제출일 '감사의견']을 입력하세요.");
            dtl_Grd2.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd2.focus();
            return false;
        }
        if (dts_Dtl2.getCellData(j, "OCCR_DD") == "") {
            $c.win.alert(j + "번째 [2. 감사의견 및 감사보고서 제출일 '일자']를 입력하세요.");
            dtl_Grd2.SetColumn("OCCR_DD");
            dtl_Grd2.focus();
            return false;
        }
        occrDd = dts_Dtl2.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            $c.win.alert(j + "번째 [2. 감사의견 및 감사보고서 제출일 '일자'] 형식을 확인하세요.");
            return false;
        }
    }
    for (j = 1; j <= dts_Dtl3.getTotalRow(); j++) {
        if (dts_Dtl3.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") == "" && dts_Dtl3.getCellData(j, "LIST_ELIGTY_PROCS_RSN_CONTN") == "") {
            $c.win.alert(j + "번째 [4. 위원회 심의결과 및 결정일자 '결과']를 입력하세요.");
            dtl_Grd3.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd3.focus();
            return false;
        }
        if (dts_Dtl3.getCellData(j, "OCCR_DD") == "") {
            $c.win.alert(j + "번째 [4. 위원회 심의결과 및 결정일자 '일자']를 입력하세요.");
            dtl_Grd3.SetColumn("OCCR_DD");
            dtl_Grd3.focus();
            return false;
        }
        occrDd = dts_Dtl3.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            $c.win.alert(j + "번째 [4. 위원회 심의결과 및 결정일자 '일자'] 형식을 확인하세요.");
            return false;
        }
        imprDd = dts_Dtl3.getCellData(j, "IMPR_DEADLINE_DD");
        isOkDate = scwin.checkDate(imprDd);
        if (!isOkDate) {
            $c.win.alert(j + "번째 [4. 위원회 심의결과 및 결정일자 '일자'] 형식을 확인하세요.");
            return false;
        }
    }
    return true;
};
scwin.checkDate = function(date) {
    var isOk = true;
    if (date.length > 0 && !$c.ut.isDate(date)) {
        isOk = false;
    }
    return isOk;
};
scwin.fn_save = function() {
    if (!scwin.fn_CheckForm()) return;
    if (!scwin.fn_checkRsnVal()) return;
    scwin.trsIdx = TRS_IDX_INSERT;
    if (!$c.lc.fn_isProcess('I')) return;
    scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
    if (scwin.vBzProcsNo.length != 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        dts_Mst.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
        scwin.setBzProcsNo();
        scwin.fn_trs();
    }
};



/*
 *	신규 입력시 업무처리번호 셋팅
 */
scwin.setBzProcsNo = function(bzProcsNo) {
    var dtl1Row = dts_Dtl1.getTotalRow();
    for (k = 1; k <= dts_Dtl1.getTotalRow(); k++) {
        dts_Dtl1.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    for (k = 1; k <= dts_Dtl2.getTotalRow(); k++) {
        dts_Dtl2.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    for (k = 1; k <= dts_Dtl3.getTotalRow(); k++) {
        dts_Dtl3.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
};
scwin.fn_update = function() {
    scwin.trsIdx = TRS_IDX_UPDATE;
    if (!scwin.fn_CheckForm()) return;
    if (!scwin.fn_checkRsnVal()) return;
    if (!$c.lc.fn_isProcess('U')) return;
    scwin.selRow = dts_List.getRowPosition();
    scwin.fn_trs();
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_trs();
};
scwin.fn_trs = function() {
    var vScrenProcTpCd;
    if (scwin.trsIdx == TRS_IDX_INSERT) {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.trsIdx == TRS_IDX_UPDATE) {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.trsIdx == TRS_IDX_DELETE) {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "REG_EMP_NO", js_id);
    trs_Save.Action = $c.lc.fn_encodeNSession("/RealInvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveRealInvstgDetail");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:dtsParm1= dts_Mst,I:dtsParam2=dts_Dtl1,I:dtsParam3=dts_Dtl2,I:dtsParam4=dts_Dtl3)";
    //trs_Save.KeyValue     = "JSP(I:dtsParm1=dts_Mst)";
    trs_Save.Parameters = "TRS_IDX=" + scwin.trsIdx + ",COUNT=0" + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_206 + ",LIST_ELIGTY_TP_CD=" + scwin.vListEligtyTpCd;
    trs_Save.Post();
};


/**
 *	그리드 행추가
 */
scwin.fn_addRow = function(bnd, grid, type) {
    bnd.addRow();
    dts_Mst.getRowPosition();
    grid.Focus();
    bnd.setCellData(bnd.getFocusedRowIndex(), "BZ_PROCS_NO", scwin.vBzProcsNo);
    if (type == "E") {
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_CD", "05");
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_RSN_CD_VAL", "DELIST_REAL_INVSTG_RSN_CD");
    } else if (type == "F") {
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_CD", "06");
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_RSN_CD_VAL", "AUDT_OPIN_TP_CD");
    } else if (type == "G") {
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_CD", "07");
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_RSN_CD_VAL", "LIST_ELIGTY_DELIB_RSLT_CD");
    }
};



/**
 *	그릳드 행삭제
 */
scwin.fn_deleteRow = function(bnd, grid) {
    var dataSet;
    if (grid == dtl_Grd1) {
        dataSet = dts_Dtl1;
    } else if (grid == dtl_Grd2) {
        dataSet = dts_Dtl2;
    } else if (grid == dtl_Grd3) {
        dataSet = dts_Dtl3;
    }
    var fileCount = Number(dataSet.getCellData(bnd.getFocusedRowIndex(), "ATTACH_FILE_CNT"));
    if (fileCount != 0) {
        if (confirm("관련파일이 존재합니다. 확인버튼 클릭시 관련파일이 바로 삭제됩니다. 삭제하시겠니까?")) {
            var bzProcsNo = dataSet.getCellData(bnd.getFocusedRowIndex(), "BZ_PROCS_NO");
            var procsCd = dataSet.getCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_CD");
            var dtlSeq = dataSet.getCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_INVSTG_DTL_SEQ");
            //dts_delRealInvstgFile.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
            dts_delRealInvstgFile.insertRow();
            dts_delRealInvstgFile.setCellData(1, "bz_procs_no", bzProcsNo);
            dts_delRealInvstgFile.setCellData(1, "list_eligty_procs_cd", procsCd);
            dts_delRealInvstgFile.setCellData(1, "list_eligty_invstg_dtl_seq", dtlSeq);
            trs_File.Action = "/RealInvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&method=realInvstgRemoveFile";
            trs_File.KeyValue = "JSP(I:pInput=dts_delRealInvstgFile)";
            trs_File.Post();
        } else {
            return;
        }
    }
    bnd.deleterow(bnd.getFocusedRowIndex());
    grid.Focus();
};


/**
 *	코드값을 그리드 콤보박스에 설정
 */
scwin.fn_searchGrdCode = function(codeName, grd) {
    var strCbdReason = "' ':"; //초기값
    for (k = 1; k <= dts_Cod.getTotalRow(); k++) {
        if (dts_Cod.getCellData(k, "CD_ENG_NM") == codeName) {
            if (codeName == "DELIST_REAL_INVSTG_RSN_CD") {
                if (dts_Cod.getCellData(k, "VALUE") != "10") {
                    strCbdReason = strCbdReason + (strCbdReason == "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
                }
            } else {
                strCbdReason = strCbdReason + (strCbdReason == "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
            }
        }
    }
    grd.setColumnProp('LIST_ELIGTY_PROCS_RSN_VAL', 'Data', strCbdReason);
};


// 첨부파일등록(이의신청서)
scwin.fn_AttachFileDtl = async function(listEligtyProcsCd) {
    if (scwin.vBzProcsNo.length != 14) {
        $c.win.alert("심사  내용을 저장 한 후, 파일을 등록하여 주십시오.");
        return;
    }
    var url = "/lstproc/ULDSTF05241_FILE.gfm?BZ_PROCS_NO=" + scwin.vBzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + listEligtyProcsCd;
    await $c.frame.CreateDialogFrame("FILE_ATTACH", url, "첨부파일 등록", 100, 100, 850, 450, "window");
};
scwin.fn_afterFile = function() {
    scwin.fn_list_allDtl_sync("05", dts_Dtl1, dts_List.getRowPosition());
    scwin.fn_list_allDtl_sync("06", dts_Dtl2, dts_List.getRowPosition());
    scwin.fn_list_allDtl_sync("07", dts_Dtl3, dts_List.getRowPosition());
};


// 첨부파일등록
scwin.fn_AttachFile = async function(dataSet, row) {
    if (dataSet.getCellData(row, "LIST_ELIGTY_INVSTG_DTL_SEQ") == "") {
        $c.win.alert("데이터를 저장 한 후, 파일을 등록하여 주십시오.");
    } else if (scwin.vBzProcsNo.length != 14) {
        $c.win.alert("심사  내용을 저장 한 후, 심의안건을 등록하여 주십시오.");
    } else {
        var procsCd = dataSet.getCellData(row, "LIST_ELIGTY_PROCS_CD");
        var dtlSeq = dataSet.getCellData(row, "LIST_ELIGTY_INVSTG_DTL_SEQ");
        var url = "/lstproc/ULDSTF05241_FILE.gfm?BZ_PROCS_NO=" + scwin.vBzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + procsCd + "&LIST_ELIGTY_INVSTG_DTL_SEQ=" + dtlSeq;
        await $c.frame.CreateDialogFrame("FILE_ATTACH", url, "첨부파일 등록", 100, 100, 850, 450, "window");
    }
};
scwin.callElasticFileNoti = function(callType) {
    var callUrl = "/index/tbld_eligty_invstg_attach/kafka";
    $.ajax({
        type: "POST",
        url: "/elasticNoti.do",
        data: {
            method: "notiEligtyFile",
            bz_procs_no: scwin.vBzProcsNo,
            url: callUrl
        },
        async: true
    });
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_New_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("회사를 선택하세요");
    } else {
        scwin.fn_initItem();
        scwin.fn_list_sync();
        scwin.fn_list_allDtl_sync("05", dts_Dtl1);
        scwin.fn_list_allDtl_sync("06", dts_Dtl2);
        scwin.fn_list_allDtl_sync("07", dts_Dtl3);
    }
};
scwin.dts_Mst_OnLoadError = function() {
    $c.stf.alert_error(dts_Mst);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
    } else {
        buttonSet.setUpdateStatus();
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    scwin.fn_initItem();
};
scwin.grd_List_OnClick = function(row, colid) {
    scwin.fn_OpenDetail(row);
    scwin.fn_list_allDtl_sync("05", dts_Dtl1, row);
    scwin.fn_list_allDtl_sync("06", dts_Dtl2, row);
    scwin.fn_list_allDtl_sync("07", dts_Dtl3, row);
};
scwin.trs_Save_OnSuccess = function() {
    var status = buttonSet.status;
    $c.lc.fn_alertMsg('S');
    scwin.fn_list_sync();
    if (status == "U") {
        dts_List.setRowPosition(scwin.selRow, 0);
        scwin.fn_OpenDetail(scwin.selRow);
    } else {
        scwin.fn_OpenDetail(dts_List.getTotalRow());
    }
    scwin.fn_afterFile();
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    //alert_error(trs_Save);	

};
scwin.img_EINSPRUCH_SUBMIT_DD_onclick = function() {
    popUpCalendar2(edt_EINSPRUCH_SUBMIT_DD);
};
scwin.img_COM_NM_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    if (chk_Yn.checked) {
        //상장폐지기업 포함 모든 목록
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } else {
        $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
    }
    scwin.fn_initItem();
    scwin.fn_list_sync();
    scwin.fn_list_allDtl_sync("05", dts_Dtl1);
    scwin.fn_list_allDtl_sync("06", dts_Dtl2);
    scwin.fn_list_allDtl_sync("07", dts_Dtl3);
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제

    buttonSet.setInsertStatus();
    $c.elw.fn_searchCode();
    dts_Mst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=REALINVSTG_DETAIL_LIST_NEW";
    dts_Mst.reset();
    scwin.fn_searchGrdCode("DELIST_REAL_INVSTG_RSN_CD", dtl_Grd1);
    scwin.fn_searchGrdCode("AUDT_OPIN_TP_CD", dtl_Grd2);
    scwin.fn_searchGrdCode("LIST_ELIGTY_DELIB_RSLT_CD", dtl_Grd3);
};
